export function getMetierByCnp(cnp: string): FicheMetier | undefined {
  return METIERS_DATA.find(m => m.cnp === cnp);
}

export function getAllMetiersCnp(): string[] {
  return METIERS_DATA.map(m => m.cnp);
}
